78	// Maximum nesting of arrays and objects in text that JSON.parse has accepted.
79	function jsonDepth(text) {
80	  let depth = 0;
81	  let max = 0;
82	  let inString = false;
83	  for (let i = 0; i < text.length; i++) {
84	    const c = text[i];
85	    if (inString) {
86	      if (c === '\\') i++;
87	      else if (c === '"') inString = false;
88	    } else if (c === '"') {
89	      inString = true;
90	    } else if (c === '[' || c === '{') {
91	      depth++;
92	      if (depth > max) max = depth;
93	    } else if (c === ']' || c === '}') {
94	      depth--;
95	    }
96	  }
97	  return max;
98	}
